arguments.command:
python - <<'PY'
from openpyxl import load_workbook
from datetime import datetime, date

path = '/root/Backup_Fuel_and_Refills_Latest.xlsx'
wb = load_workbook(path, data_only=True)
print('Workbook:', path)
print('Sheet names:', wb.sheetnames)
print('---')

def fmt_value(v):
    if isinstance(v, datetime):
        return f"datetime({v.isoformat()})"
    if isinstance(v, date):
        return f"date({v.isoformat()})"
    return repr(v)

def cell_type(v):
    if v is None:
        return 'None'
    if isinstance(v, bool):
        return 'bool'
    if isinstance(v, int):
        return 'int'
    if isinstance(v, float):
        return 'float'
    if isinstance(v, datetime):
        return 'datetime'
    if isinstance(v, date):
        return 'date'
    return type(v).__name__

def dump_sheet(name):
    ws = wb[name]
    print(f"SHEET: {name}")
    print(f"  max_row={ws.max_row} max_col={ws.max_column}")

    # Explicitly call out key metadata cells if present
    for coord in ['B1','D1']:
        c = ws[coord]
        print(f"  {name}!{coord} -> value={fmt_value(c.value)} type={cell_type(c.value)} number_format={repr(c.number_format)}")
    print('  FULL CONTENT:')

    # Print every row up to max_row, every column up to max_column
    # Represent as a grid with coordinates for unambiguous positions.
    for r in range(1, ws.max_row + 1):
        row_cells = []
        for col in range(1, ws.max_column + 1):
            c = ws.cell(row=r, column=col)
            row_cells.append(f"{c.coordinate}={fmt_value(c.value)}")
        print(f"  Row {r}: " + ' | '.join(row_cells))
    print('---')

for sheet in ['Current Fuel', 'Scheduled Refills', 'Policy Parameters']:
    dump_sheet(sheet)
PY

